"""Create a controlled, partially-observable reference corpus without fake labels."""
import argparse, hashlib, json
from pathlib import Path
DIMS=['data','logic','quality','freshness','review','capability','resource','risk','downstreamImpact','uncertainty']
REL=['data_transfer','review_handoff','versioned_result','resource_gate','plan_dependency']
def load(p): return [json.loads(x) for x in Path(p).read_text(encoding='utf8').splitlines() if x.strip()]
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--public',required=True); ap.add_argument('--gold',required=True); ap.add_argument('--output',required=True); a=ap.parse_args(); out=Path(a.output); out.mkdir(parents=True,exist_ok=False)
 pub={x['id']:x for x in load(a.public)}; gold={x['id']:x for x in load(a.gold)}; rows=[]
 for idx,(ident,p) in enumerate(sorted(pub.items())):
  g=gold.get(ident,{}); pair=[f'agent-{idx%11:02d}',f'agent-{(idx*3+1)%17:02d}']; rel=REL[idx%len(REL)]; sg=g.get('stateGold') or []
  edge_gold={}
  for ei,e in enumerate(p.get('edges',[])):
   s=sg[ei%len(sg)] if sg else {}; known={'data':s}
   dims={}
   for d in DIMS:
    if d in known: x=known[d]; dims[d]={'mean':float(x.get('mean',0)),'interval':x.get('interval',[0,1]),'status':x.get('status','UNKNOWN'),'evidenceRefs':e.get('public',{}).get('evidenceRefs',[]),'sourceVersion':'tdb-controlled-evaluator-v1','label_mask':bool(x.get('label_mask'))}
    else: dims[d]={'mean':None,'interval':[0,1],'status':'UNKNOWN','evidenceRefs':[],'sourceVersion':'not_observed','label_mask':False}
   edge_gold[e['edgeId']]={'dimensions':dims,'labelSource':'independent_controlled_evaluator_partial'}
  t='2026-01-01T00:00:'; conv=[{'id':f'{ident}-m{i}','role':role,'actorUserId':pair[i%2],'content':text,'occurredAt':t+f'{i:02d}Z'} for i,(role,text) in enumerate([('requester','State the acceptance criteria and evidence required.'),('recipient',f'I will inspect relation {rel} and report a versioned result.'),('recipient','I found the public dependency observation and checked its evidence reference.'),('requester','Return only the minimum fields required for the decision.'),('recipient','Result submitted; independent review is still required.'),('requester','Acknowledged; wait for independent certification.')])]
  tools=[{'toolCallId':f'{ident}-tc0','actorUserId':pair[1],'name':'read_dependency_snapshot','arguments':{'edgeId':e.get('edgeId','')},'result':{'status':'ok','evidenceRefs':e.get('public',{}).get('evidenceRefs',[])}} for e in p.get('edges',[])[:1]]
  events=[{'eventKind':k,'sourceKind':'synthetic_controlled_evaluator','occurredAt':t+f'{i:02d}Z'} for i,k in enumerate(['task_created','plan_published','dependency_inspected','tool_called','tool_returned','handoff_sent','result_submitted','review_pending'])]
  proj=g.get('projectionGold') or {}; util=g.get('utilityGold') or {}; candidate=max(util,key=util.get) if util else 'noop'
  rows.append({'schemaVersion':'tdb-episode-contract-v1','taskFamilyId':p['familyId'],'taskInstanceId':ident,'episodeId':ident,'agentPair':pair,'conversation':conv,'toolTrace':tools,'eventTrace':events,'gPlan':{'nodes':pair,'edges':[{'edgeId':e['edgeId'],'from':pair[0],'to':pair[1],'relationType':rel} for e in p.get('edges',[])]},'gExec':{'nodes':pair,'edges':[{'edgeId':e['edgeId'],'from':pair[0],'to':pair[1],'relationType':rel,'status':'observed'} for e in p.get('edges',[])]},'tdbPlan':{'dimensions':{d:{'mean':None,'status':'UNKNOWN','label_mask':False} for d in DIMS}},'tdbActiveTrace':events,'tdbExec':{'dimensions':{d:{'mean':None,'status':'UNKNOWN','label_mask':False} for d in DIMS}},'receiverScope':{'role':'downstream_agent','allowedFields':['tdb','resultVersion','evidence']},'decisionQuery':'accept_result','privacyPolicy':{'allowedFields':['tdb','resultVersion','evidence'],'privateFieldsExcluded':True},'hardContract':{'independentCheckerRequired':True},'dependencyGold':edge_gold,'disclosureGold':{'status':'REFERENCE' if proj.get('status')!='UNKNOWN' else 'UNKNOWN','selectedUnits':proj.get('selectedUnits',[]),'decision':proj.get('decision','UNKNOWN'),'privacySafe':bool(proj.get('privacySafe',True)),'disclosureCost':proj.get('disclosureCost'),'labelSource':'independent_projection_solver'},'evolutionGold':{'candidateEdgeId':candidate,'causeSet':['edge'] if candidate!='noop' else [],'labelSource':'paired_noop_controlled_evaluator'},'evaluatorVersion':'tdb-controlled-evaluator-v1','sourceProvenance':{'kind':'synthetic_reference','publicId':ident,'goldId':ident,'hiddenWorldExcludedFromPrompt':True,'labelPolicy':'unsupported_dimensions_unknown'},'replayToken':hashlib.sha256((ident+'-replay-v3').encode()).hexdigest(),'traceHash':hashlib.sha256(json.dumps(events,sort_keys=True).encode()).hexdigest(),'labelMask':{'dependency':True,'disclosure':True,'evolution':True},'split':p.get('split','train')})
 (out/'episodes.jsonl').write_text(''.join(json.dumps(x,ensure_ascii=False)+'\n' for x in rows),encoding='utf8'); (out/'manifest.json').write_text(json.dumps({'schemaVersion':'tdb-full-episode-reference-v3','rows':len(rows),'evidenceLevel':'SYNTHETIC_FINITE_WORLD_REFERENCE','unsupportedDimensionsAreUnknown':True,'independentGoldNotModelInput':True,'publicSha256':hashlib.sha256(Path(a.public).read_bytes()).hexdigest(),'goldSha256':hashlib.sha256(Path(a.gold).read_bytes()).hexdigest()},ensure_ascii=False,indent=2),encoding='utf8'); print(json.dumps({'rows':len(rows),'output':str(out.resolve())}))
if __name__=='__main__': main()
